local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[406804]=b({e[24034],406804,5,118,340,"「どう？　素敵でしょ、この晴れ着。けど、どうしても動きにくいわね……。ねえ、私を起こしてもらえる？　それとも、一緒に寝ころびたい？」",200068,2,"deco/character/406804",false,false,false,false,1,false,false,"1",false,"0,120,0.95","-250,120,0.95","240,-140,0.89","-250,120,0.95","-250,120,0.95","-60,60,0.95",2255,1049,398,553,28,2979,3356,592,747,2901,1261,1,1489,5000,733,1293,5333,10000,7500,8000,13000,8000,5333,false,false,0},h)g[406805]=b({e[17045],406805,9,31,341,"「あなたが来るまで、のんびりゴロゴロ……。\nこうしてると、あなたと一緒に過ごすことが、\nすごく自然なことのように感じられるのよね。\nなんだか安心して、眠くなってきちゃうわ～……。」",200068,2,"deco/character/406805",false,false,false,false,false,false,false,"",1,3164,5000,1627,3067,8000,8666,16666,5500,14000,8000,8000,false,false,0},h)g[406901]=b({e[46057],406901,false,149,342,false,200069,false,"deco/character/weilai",302002,60,1,false,false,false,-22,"1",false,false,false,false,false,false,false,"100,130,1","40,10,1","-50,20,1","40,10,1","-50,20,1",false,"-90,0,1","-40,0,1","-90,0,1","-40,0,1",false,1907,852,386,1044,777,1884,2614,1044,777,1884,1028,"weilai"},h)g[406902]=b({e[11034],406902,1,4,343,"「パラレルワールドって、聞いたことある？\n研究によると、僕たちが何かしらの選択をするたびに、別の世界が誕生するらしいよ。\nだからたまに思うんだ。あの日、ベーカーズをキミにぶつけたのも、ある種の幸運だったんじゃないかって。\n少なくとも、その時に僕達が出会う世界……新たな未来が生まれたってことになるからね。」",200069,1,"deco/character/weilai_0",302002,60,1842,833,392,741,436,2827,2963,741,528,2827,1261,false,false,false,false,false,false,false,false,false,false,false,false,"weilai_0"},h)g[406903]=b({e[46057],406903,12,133,344,"「全く、こんな複雑なデザイン、端から一人で着ることを想定してないんだろうね。まぁいいや。僕はキミのためにこれを着たんだから、この後メンテしなきゃいけなくなったら最後まできっちり付き合ってくれよ。」",200069,2,"deco/character/weilai_LF",false,false,1,false,false,false,false,"1",false,false,"-80,0,1",false,"-60,0,1","-60,0,1","-100,0,1",false,false,false,false,false,false,false,false,false,false,false,1956,883,392,1068,714,2063,2510,1068,714,2063,1125,"weilai_lf"},h)g[406904]=b({e[9057],406904,17,72,345,"優雅に踊るヒューマノイドを開発するには、モニタの前でひたすらデータとにらめっこしててもしょうがない。やっぱり、自分で色々なダンスをやってみる必要があると思うんだ。\nほっ……ねえ、ちょっと、足を支えててくれない？ あと少しで、つま先に届く、はず、なんだけ、ど……。\nそう、そんな感じで……！　って、あれ？　なんだか、キミの手のひら、すごく熱くない？",200069,2,"deco/character/weilai_BL","weilai_bl"},h)g[407001]=b({e[25034],407001,false,150,346,false,200070,false,"deco/character/luluxiu",302002,60,1,false,false,false,-160,"1",false,false,false,false,false,false,false,"40,590,0.94",1872,863,388,1507,780,1016,3194,1507,780,1016,1037},h)g[407002]=b({e[24034],407002,1,4,347,false,200070,1,"deco/character/luluxiu_0",302002,60,false,false,1,false,false,false,false,"0,-104,1","0,-88,1",false,"0,-90,1",false,"0,-110,1",1837,744,388,683,388,3455,3812,960,437,2901,1261},h)g[407003]=b({e[12034],407003,999,151,348,false,200070,3,"deco/character/luluxiu_dress",false,false,1,1734,912,388,823,416,3079,3013,912,605,2901,1261},h)g[407101]=b({e[25034],407101,false,152,349,false,200071,false,"deco/character/cc",302002,60,1,false,false,false,-73,"1",false,false,false,false,false,false,false,"60,340,0.94",1846,876,388,1323,815,1609,2876,1323,815,1609,1015},h)g[407102]=b({e[12034],407102,1,4,350,false,200071,1,"deco/character/cc_0",302002,60,1,1980,937,388,579,false,2888,3926,579,630,2888,1261},h)g[407103]=b({e[12034],407103,999,151,351,false,200071,3,"deco/character/cc_dress",false,false,1,1879,872,388,1130,112,2217,3091,1130,565,2217,1261},h)g[407201]=b({e[25034],407201,false,153,352,false,200072,false,"deco/character/zhuque",302002,60,false,false,false,false,-210,"0.980000019073486",false,false,false,false,false,false,false,"20,610,0.94",1850,826,388,1484,719,1084,3292,1484,719,1084,1061},h)g[407202]=b({e[12034],407202,1,4,353,false,200072,1,"deco/character/zhuque_0",302002,60,1,1848,820,388,809,512,2670,3688,809,513,2670,1261},h)g[407203]=b({e[12034],407203,999,151,354,false,200072,3,"deco/character/zhuque_dress",false,false,1,1901,912,388,371,380,3184,3076,512,605,2902,1261},h)g[407301]=b({e[25034],407301,false,154,355,false,200073,false